// Baseline for H-10: particleWorker BEFORE the sway bucket cache.
//
// The point of the rule "content checks are not validity checks" applies here
// twice over. A baseline that merely *looks* like the old file proves nothing;
// this one is generated by reversing the exact edit and then checked for the
// markers that make it the old version and not the new one.
//
// The reversal is mechanical because the change was two hunks with unique
// anchors. Anything that cannot be reversed exactly must fail loudly rather than
// emit a baseline that is subtly the new code.

import fs from 'node:fs';
import path from 'node:path';

const SRC = 'src/workers/particleWorker.js';
const OUT = 'tests/results/hyp-baselines/H10.particleWorker.nocache.js';

// Normalise to LF before any matching.
//
// The working tree is CRLF, so an LF needle never matches and the guard below
// fails with "found 0" for the right reason at the wrong cause. Line endings
// carry no meaning to the module, so normalising cannot change what is measured -
// but it must be done explicitly, because a generator that silently emits a
// baseline it could not verify is the exact failure this file exists to prevent.
const source = fs.readFileSync(SRC, 'utf8').replace(/\r\n/g, '\n');

// --- 1. the allocation hunk -------------------------------------------------
const ALLOC_NEW = `        // Uint16, NOT Uint8: \`swayFrequencyBuckets\` is read straight from config with
        // no upper bound, so a grid above 256 would wrap a Uint8 cache and hand
        // back the wrong bucket - a decoration swaying at another decoration's
        // frequency. 65535 buckets is far past any sane grid and the cache still
        // costs two bytes per decoration.
        this._swayBucketOf = new Uint16Array(this.maxDecorations);
        this._swayBucketFreq = new Float32Array(this.maxDecorations);
        // A sentinel no real frequency can equal, so the first read always misses.
        this._swayBucketFreq.fill(-1);
        // The bucket count the cache was populated for; k can be reconfigured.
        this._swayBucketCacheK = this._swayBuckets;
`;
const ALLOC_OLD = '';

// --- 2. the hot-loop hunk ---------------------------------------------------
const LOOP_NEW = `    // A reconfigured bucket count invalidates every cached bucket at once.
    if (this._swayBucketCacheK !== k) {
      this._swayBucketCacheK = k;
      this._swayBucketFreq.fill(-1);
    }
    const bucketOf = this._swayBucketOf;
    const bucketFreq = this._swayBucketFreq;
    const noParent = this._noParent;

`;
const LOOP_BODY_NEW = `        // Self-validating bucket cache.
        //
        // \`bucketFromSwayFrequency\` recomputes \`2 / (k - 1)\`, then divides,
        // rounds and clamps - per decoration, per frame. The loop above already
        // hoists the sin/cos for exactly this reason ("chosen once per frame so
        // the hot path has no fallback into Math.sin"), and this call was the
        // same mistake one layer down.
        //
        // A steady state hit is two typed-array reads and a float compare,
        // replacing a division. A miss recomputes and revalidates, so a
        // decoration whose swayFrequency changed is correct on the same frame it
        // changes - there is no window in which the cache is wrong.
        const f = swayFrequency[i];
        let b = bucketOf[i];
        if (bucketFreq[i] !== f) {
          b = bucketFromSwayFrequency(f, k);
          bucketOf[i] = b;
          bucketFreq[i] = f;
        }
`;
const LOOP_BODY_OLD = `        const b = bucketFromSwayFrequency(swayFrequency[i], k);
`;

let out = source;

function mustHave(hay, needle, what) {
  const n = hay.split(needle).length - 1;
  if (n !== 1) throw new Error(`${what}: expected exactly 1 occurrence, found ${n}`);
}

function mustNotHave(hay, needle, what) {
  if (hay.includes(needle)) throw new Error(`${what}: baseline would still contain it`);
}

mustHave(out, ALLOC_NEW, 'allocation hunk');
mustHave(out, LOOP_NEW, 'loop preamble hunk');
mustHave(out, LOOP_BODY_NEW, 'loop body hunk');

out = out.replace(ALLOC_NEW, ALLOC_OLD);
// The preamble is pure addition, so its pre-change form is nothing at all.
// (`?? ''` does not help here: an undeclared binding throws, it is not undefined.)
out = out.replace(LOOP_NEW, '');
out = out.replace(LOOP_BODY_NEW, LOOP_BODY_OLD);

// The loop preamble used `noParent`; without it the old body must reference
// `this._noParent` again.
out = out.replace(
  'if (parentEntityIndex[i] !== noParent) continue;',
  'if (parentEntityIndex[i] !== this._noParent) continue;',
);

// --- validity, not just content --------------------------------------------
mustNotHave(out, '_swayBucketOf', 'cache allocation');
mustNotHave(out, 'bucketFreq', 'cache read');
mustNotHave(out, '_swayBucketCacheK', 'cache invalidation');
mustHave(out, 'const b = bucketFromSwayFrequency(swayFrequency[i], k);', 'original lookup');

// The parent guard is hoisted in the bucketed loop, so the change REMOVED one
// `this._noParent` reference. A correct reversal therefore has exactly one more
// occurrence than the current source - and that difference is itself the proof
// the reversal was complete rather than approximate.
const PARENT_GUARD = 'if (parentEntityIndex[i] !== this._noParent) continue;';
const before = source.split(PARENT_GUARD).length - 1;
const after = out.split(PARENT_GUARD).length - 1;
if (after !== before + 1) {
  throw new Error(
    `parent guard: source has ${before}, baseline has ${after}; expected ` +
      `${before + 1} (the hoist removed one, so the reversal restores one). ` +
      `${after > before ? 'Over-applied.' : 'Under-applied - the hoist was not reverted.'}`,
  );
}
// The one thing that must survive: the hoisted sin/cos, which is pre-existing.
mustHave(out, 'sA[b] = Math.sin(a);', 'hoisted sin');

fs.mkdirSync(path.dirname(OUT), { recursive: true });
fs.writeFileSync(OUT, out, 'utf8');

console.log(`baseline written: ${OUT}`);
console.log(`  ${source.split('\n').length} lines -> ${out.split('\n').length} lines`);
console.log('  validity checks passed: no cache symbols, original lookup present,');
console.log('  parent guard restored, hoisted sin/cos intact.');